const values = [10, 20, 30];

// With <= (buggy):
// i = 0, 1, 2 → adds 10, 20, 30
// i = 3 → adds undefined → total becomes NaN

// With < (correct):
// i = 0, 1, 2 → adds 10, 20, 30
// Loop ends before accessing index 3
```

